"""Tests for detect.py. Run with: python test_detect.py   (or: python -m pytest test_detect.py)"""

from detect import detect


def ev(time, event, ip="203.0.113.9", user="alice"):
    return {"time": f"2026-10-05T{time}Z", "source": "test", "event": event, "src_ip": ip, "user": user}


def test_four_failures_are_quiet():
    events = [ev(f"10:00:{s:02d}", "login_failure") for s in (0, 10, 20, 30)]
    assert detect(events) == []


def test_fifth_failure_within_two_minutes_alerts_once():
    events = [ev(f"10:00:{s:02d}", "login_failure") for s in (0, 10, 20, 30, 40, 50)]
    assert detect(events) == [("2026-10-05T10:00:40Z", "brute_force", "203.0.113.9", "5 failures in 120s")]


def test_slow_failures_are_quiet():
    events = [ev(f"10:{m:02d}:00", "login_failure") for m in (0, 3, 6, 9, 12)]
    assert detect(events) == []


def test_addresses_are_counted_separately():
    events = [ev(f"10:00:0{n}", "login_failure", ip=f"203.0.113.{n}") for n in (1, 2, 3, 4, 5)]
    assert detect(events) == []


def test_success_after_three_failures_alerts():
    events = [ev(f"10:0{m}:00", "login_failure") for m in (0, 2, 4)] + [ev("10:06:00", "login_success")]
    assert detect(events) == [("2026-10-05T10:06:00Z", "success_after_failures", "203.0.113.9", "alice after 3 failures")]


def test_success_alone_is_quiet():
    assert detect([ev("10:00:00", "login_success")]) == []


if __name__ == "__main__":
    tests = [f for name, f in sorted(globals().items()) if name.startswith("test_")]
    for test in tests:
        test()
    print(f"{len(tests)} tests passed")

"""Add context to each alert in alerts.csv, from the asset list, the scanner allowlist,
staff office addresses and approved changes.

Usage: python triage_helper.py
"""

import csv


def read_csv(path):
    with open(path, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def read_scanners(path):
    """Return {address: reason} from a file of 'address reason' lines (# starts a comment)."""
    scanners = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith("#"):
                address, reason = line.split(maxsplit=1)
                scanners[address] = reason
    return scanners


def context_for(alert, assets, scanners, office, changes):
    """Return a list of short notes that help an analyst triage the alert."""
    notes = []
    asset = assets.get(alert["host"])
    if asset:
        notes.append(f"{alert['host']}: {asset['criticality']} criticality, {asset['role']}")
    # TODO 1: if alert["src_ip"] is in scanners, add the note  allowlisted scanner: <reason>
    # TODO 2: if alert["src_ip"] is a staff office address, add the note  office address of <user>
    # TODO 3: for each change on the alert's host whose start_utc <= alert["time_utc"] <= end_utc,
    #         add the note  approved change <change_id>: <description>
    return notes


def main():
    assets = {a["host"]: a for a in read_csv("assets.csv")}
    scanners = read_scanners("scanner_allowlist.txt")
    office = {s["office_ip"]: s["user"] for s in read_csv("staff.csv")}
    changes = read_csv("changes.csv")
    for alert in read_csv("alerts.csv"):
        print(f"{alert['alert_id']}  {alert['rule']}  {alert['src_ip'] or alert['user']}")
        for note in context_for(alert, assets, scanners, office, changes):
            print(f"    - {note}")


if __name__ == "__main__":
    main()
